# PostgreSQL locking variants have their own reviewed SQL fingerprints.
for _key in ("account_get", "window_get", "hold_get", "guard_get"):
    SQL[_key + "_locked"] = SQL[_key] + " FOR UPDATE"
SQL["outbox_due_locked"] = SQL["outbox_due"] + " FOR UPDATE SKIP LOCKED"

